function renderPrivacyPage(){const m=state.settings.merchant||{},rows=[['Vendeur',m.legalName],['E-mail',m.email],['Téléphone',m.phone],['Adresse',m.address]].filter(([,v])=>v),complete=['legalName','email','phone','address'].every(k=>String(m[k]||'').trim());$('#legalView').innerHTML='<section><p class="eyebrow">VOS DONNÉES</p><h1>Confidentialité et données personnelles</h1><p>MacouraShop utilise uniquement les informations nécessaires pour enregistrer, préparer, livrer et suivre les commandes, gérer les paiements déclarés, les annulations et les retours, et répondre aux demandes des clientes.</p><h2>Données utilisées</h2><p>Selon le parcours choisi, il peut s’agir du nom, du téléphone, de l’adresse e-mail, de l’adresse de livraison, des articles commandés, du moyen de paiement choisi, de l’historique de traitement et des justificatifs transmis volontairement.</p><h2>Accès et sécurité</h2><p>Les informations de commande sont accessibles à la cliente concernée au moyen de son compte ou de son téléphone associé au code confidentiel, ainsi qu’au gérant authentifié. Le paiement à la livraison ne nécessite aucune donnée de carte bancaire sur MacouraShop. Le code de suivi ne doit pas être partagé.</p><h2>Conservation</h2><p>Les informations sont conservées pendant la durée nécessaire au traitement de la commande, du service après-vente et des obligations administratives, comptables ou légales applicables. Elles ne sont pas utilisées pour une prospection automatique sur le site.</p><h2>Vos demandes</h2><p>Pour demander l’accès, la correction ou la suppression de données lorsqu’elle est possible, contactez le vendeur aux coordonnées indiquées ci-dessous. Certaines informations peuvent devoir être conservées pour respecter une obligation légale ou assurer la preuve d’une transaction.</p>'+(rows.length?'<h2>Contact responsable</h2><dl class="legal-details">'+rows.map(([k,v])=>'<div><dt>'+k+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl>':'')+(!complete?'<p class="notice"><b>Avant l’ouverture publique :</b> les coordonnées du vendeur doivent être complètes afin que toute demande puisse recevoir une réponse.</p>':'')+'<p><a class="primary" href="/#boutique">Retour à la boutique</a></p></section>'}
function priceLabel(p){const legacy=effectivePrice(p,currency),offer=productOffer(p,state.settings,currency),fixed=currency==='EUR'?offer?.priceEUR:offer?.priceXOF,actual=offer?.type==='fixed_price'&&Number.isSafeInteger(fixed)&&fixed<legacy?fixed:offer?.type==='product_percent'?legacy-Math.round(legacy*offer.percent/100):legacy,base=currency==='EUR'?p.eur:p.xof;return (actual<base?'<del class="old-price">'+money(base)+'</del> ':'')+money(actual)}
