function collectionLinks(){return ['Tout',...CATS].map(c=>'<a href="/#catalogue?collection='+encodeURIComponent(c)+'" data-collection="'+esc(c)+'">'+(c==='Tout'?'Toutes les collections':esc(c))+'</a>').join('')}
