function applyCollectionRoute(){
 if(!location.hash.startsWith('#catalogue?'))return;
 const value=new URLSearchParams(location.hash.slice(location.hash.indexOf('?')+1)).get('collection');
 if(!['Tout',...CATS].includes(value))return;
 if(category!==value){search='';$('#search').value=''}category=value;favoritesOnly=false;
}
function mountCollectionMenus(){
 const menus=$$('.collection-menu');
 menus.forEach(menu=>{
  menu.querySelector('.collection-list').innerHTML=collectionLinks();
  menu.addEventListener('toggle',()=>{if(menu.open)menus.forEach(other=>{if(other!==menu)other.open=false})});
  menu.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.open=false;menu.querySelector('summary').focus()}});
  menu.addEventListener('focusout',e=>{if(!menu.contains(e.relatedTarget))menu.open=false});
  menu.querySelectorAll('[data-collection]').forEach(a=>a.onclick=()=>{
   menu.open=false;
   if(location.pathname!=='/admin'&&location.hash===a.hash)route();
  });
 });
 document.addEventListener('pointerdown',e=>menus.forEach(menu=>{if(!menu.contains(e.target))menu.open=false}));
 syncCollectionMenu();
}
