 const method=mode();$('#contactFields').hidden=false;$('#contactFields').querySelectorAll('input').forEach(i=>i.disabled=false);
 $('#addressFields').hidden=method!=='address';$('#addressFields').querySelectorAll('input,textarea').forEach(i=>i.disabled=method!=='address');$('#whatsappFields').hidden=method!=='whatsapp';$('#whatsappFields').querySelectorAll('input').forEach(i=>i.disabled=method!=='whatsapp');
