 const quote=currentQuote(z),subtotal=quote.subtotal,min=currency==='EUR'?rules.minimumEUR:rules.minimumXOF,methods=z?paymentMethods(z.country,state.settings.payments,z):[];
 const selected=methods.some(x=>x.id===checkoutDraft.payment)?checkoutDraft.payment:(methods.length===1?methods[0].id:'');checkoutDraft.payment=selected;
 $('#checkoutTotals').innerHTML=(quote.productDiscount?'<div class="summary-line offer-saving"><span>Réduction articles</span><b>− '+money(quote.productDiscount)+'</b></div>':'')+'<div class="summary-line"><span>Articles</span><b>'+money(subtotal)+'</b></div><div class="summary-line"><span>Livraison</span><b>'+(z?money(quote.shipping):'À sélectionner')+'</b></div>'+(quote.shippingDiscount?'<div class="summary-line offer-saving"><span>Offre livraison</span><b>− '+money(quote.shippingDiscount)+'</b></div>':'')+(z?'<p class="muted">'+esc(z.delay||'Délai à confirmer par le gérant')+'</p><div class="summary-line"><strong>Total à régler</strong><b>'+money(quote.total)+'</b></div>':'')+(min>subtotal?'<p class="notice">Minimum hors livraison : '+money(min)+'. Ajoutez '+money(min-subtotal)+' d’articles.</p>':'')+(methods.length?'<fieldset class="payment-picker"><legend>Moyen de paiement *</legend>'+methods.map(x=>'<label class="payment-option"><input form="checkoutForm" type="radio" name="payment" value="'+x.id+'" '+(x.id===selected?'checked':'')+'><span><b>'+esc(x.label)+'</b><small>'+esc(x.detail)+(x.test?' · MODE TEST':'')+'</small></span>'+(x.test?'<em>TEST</em>':'')+'</label>').join('')+'</fieldset>':'<p class="notice">'+(z?'Aucun moyen de paiement actif pour cette zone.':'Choisissez votre destination pour connaître les moyens de paiement.')+'</p>');
 $$('[name=payment]').forEach(input=>input.onchange=()=>{checkoutDraft.payment=input.value;totals()});
