function orderProofCard(o){const proof=o.details?.proof,url='/api/admin/order/'+encodeURIComponent(o.id)+'/proof';return '<section class="record-card order-proof"><h3>Preuve de commande</h3><p>'+sourceBadge(o)+'</p>'+(proof?'<p><b>'+esc(proof.name)+'</b><br><small>Ajoutée le '+new Date(proof.created).toLocaleString('fr-FR')+'</small></p><a class="secondary" href="'+url+'" target="_blank" rel="noopener">Voir la preuve</a><p class="muted">Vous pouvez la remplacer ci-dessous.</p>':'<p class="muted">Aucune capture ou confirmation jointe.</p>')+'<label>Ajouter ou remplacer<input id="orderProofInput" type="file" accept="image/jpeg,image/png,image/webp,application/pdf"></label><button class="secondary" id="uploadOrderProof" disabled>Enregistrer la preuve</button><p class="inline-error" role="alert"></p></section>'}
