 const articles='<section class="record-card"><h3>2. Articles à préparer</h3>'+o.lines.map(l=>'<div class="summary-line"><span><b>'+esc(l.name)+'</b><br><small>Taille '+esc(l.size)+' · Couleur '+esc(l.color)+' · Quantité '+l.quantity+'</small></span><b>'+money(l.price*l.quantity,o.currency)+'</b></div>').join('')+(o.details?.pricing?.productDiscount?'<div class="summary-line offer-saving"><span>Réductions appliquées</span><b>− '+money(o.details.pricing.productDiscount,o.currency)+'</b></div>':'')+'<div class="summary-line"><span>Livraison facturée à la cliente</span><b>'+money(o.shipping,o.currency)+'</b></div>'+(o.details?.pricing?.shippingDiscount?'<p class="muted">Tarif normal '+money(o.details.pricing.shippingBase,o.currency)+' · offre livraison − '+money(o.details.pricing.shippingDiscount,o.currency)+'</p>':'')+'<div class="summary-line"><b>Total de la commande</b><b>'+money(o.total,o.currency)+'</b></div></section>';
