let stockTab='state',stockRequest=0;
const STOCK_TYPES={entry:'Entrée de stock',correction_add:'Correction positive',correction_remove:'Correction négative',unusable:'Mise à l’écart',restore:'Remise en vente',discard:'Sortie définitive',inventory:'Inventaire physique'};
function stockVariantLabel(row){return row.name+' — '+row.size+' / '+row.color}
function stockMovementLabel(type){return STOCK_TYPES[type]||type}
function stockStatus(row){return row.available===0?['Rupture','empty']:row.available<=3?['Stock faible','low']:['En stock','ok']}
