function productCostFields(p){
 return '<section class="cost-panel"><h3>Prix d’achat, transport & marge — privé</h3><p class="muted">Coûts par unité, dans chaque devise. Le transport correspond à l’acheminement vers votre stock, pas à la livraison au client. Vide = inconnu ; 0 = aucun coût. Les coûts sont copiés dans chaque nouvelle commande.</p>'+['EUR','XOF'].map(c=>'<fieldset><legend>'+c+'</legend><div class="form-grid">'+[['purchase','Prix d’achat par unité'],['transport','Acheminement par unité']].map(([key,label])=>'<label>'+label+'<input name="cost_'+c+'_'+key+'" type="number" min="0" step="'+(c==='EUR'?'0.01':'1')+'" value="'+(p.costs?.[c]?.[key]==null?'':c==='EUR'?p.costs[c][key]/100:p.costs[c][key])+'"></label>').join('')+'</div><p class="muted" id="margin'+c+'"></p></fieldset>').join('')+'</section>';
}
function readProductCosts(form){const result={};for(const c of ['EUR','XOF']){result[c]={};for(const key of ['purchase','transport']){const raw=form.elements['cost_'+c+'_'+key].value;result[c][key]=raw===''?null:Math.round(Number(raw)*(c==='EUR'?100:1))}}return result}
function mountProductMargins(){
 const form=$('#productForm'),update=()=>{const costs=readProductCosts(form);for(const c of ['EUR','XOF']){
  const factor=c==='EUR'?100:1,base=Math.round(Number(form.elements[c==='EUR'?'eur':'xof'].value)*factor),p=costs[c],result=productMarginPreview({base,promotion:null,promotionEnabled:false,purchase:p.purchase,transport:p.transport}),box=$('#margin'+c);
  box.classList.remove('margin-positive','margin-negative','margin-incomplete');
  if(!result.complete){box.classList.add('margin-incomplete');box.textContent='Formule : prix de vente appliqué − prix d’achat − acheminement = marge. Renseignez les deux coûts pour obtenir le résultat.';continue}
  const priceLabel='prix catalogue hors campagne';
  box.classList.add(result.margin<0?'margin-negative':'margin-positive');
  box.textContent='Prix utilisé : '+money(result.sale,c)+' ('+priceLabel+'). Calcul : '+money(result.sale,c)+' − '+money(p.purchase,c)+' − '+money(p.transport,c)+' = '+money(result.margin,c)+(result.margin<0?' · Attention : vente à perte avant livraison client et frais généraux.':'');
 }};
 form.addEventListener('input',update);update();
}
let financePeriod={from:'',to:''},financeRequest=0,financeCurrency='EUR';
function financeWorkspace(data,c){
 const v=data[c],amount=n=>n==null?'À renseigner':money(n,c);
 const cards=[['Encaissé',money(v.received,c),'Paiements réellement déclarés reçus'],['À encaisser',money(v.outstanding,c),'Commandes actives non payées'],['Ventes livrées',money(v.deliveredSales,c),'Commandes livrées non remboursées'],['Résultat estimé',v.estimatedResult==null?'Calcul en attente':money(v.estimatedResult,c),'Ventes livrées − dépenses enregistrées']];
 return '<div class="stats finance-main-metrics">'+cards.map(([label,value,hint])=>'<article><span>'+label+'</span><b>'+value+'</b><small>'+hint+'</small></article>').join('')+'</div>'+(v.incomplete?'<div class="finance-cost-alert"><div><strong>'+v.incomplete+' commande(s) livrée(s) avec des montants manquants</strong><p>Le coût d’achat, l’acheminement ou la livraison réelle doit être renseigné. La commande reste modifiable même après livraison.</p></div><button class="secondary" id="financeMissingCosts">Afficher les commandes</button></div><div id="financeMissingList" aria-live="polite"></div>':'')+'<details class="finance-breakdown"><summary>Comprendre le calcul du résultat</summary><div class="finance-calculation">'+[['Ventes livrées',amount(v.deliveredSales)],['− Achat des articles livrés',amount(v.purchase)],['− Acheminement et livraison réelle',amount(v.transport)],['− Frais généraux enregistrés',amount(v.overhead)],['= Résultat estimé',v.estimatedResult==null?'Calcul en attente':amount(v.estimatedResult)]].map(([label,value])=>'<div class="summary-line"><span>'+label+'</span><b>'+value+'</b></div>').join('')+'</div><p class="muted">Ce résultat porte sur les commandes livrées non remboursées. Il ne représente pas le solde bancaire et reste hors taxes.</p></details><details class="finance-breakdown"><summary>Montant des commandes enregistrées</summary><p>'+v.orders+' commande(s), hors annulations, rejets et remboursements · '+money(v.ordered,c)+'. Ce montant inclut les commandes non livrées : ce n’est pas le résultat.</p></details>';
}
async function renderFinances(root){
 const request=++financeRequest;root.innerHTML='<p role="status">Chargement du bilan…</p>';
 try{
 const data=await api('/api/admin/finances?'+new URLSearchParams(financePeriod));if(section!=='finances'||request!==financeRequest)return;
 root.innerHTML='<section class="finance-workspace"><div class="finance-controls"><div class="order-buckets" aria-label="Devise du bilan">'+['EUR','XOF'].map(c=>'<button class="secondary" data-finance-currency="'+c+'" aria-pressed="'+(c===financeCurrency)+'">'+(c==='EUR'?'Euro · EUR':'Franc CFA · XOF')+'</button>').join('')+'</div><button class="secondary" id="financeExport">Rapport & téléchargements</button></div><form id="financePeriod" class="finance-period"><label>Commandes créées du<input type="date" name="from" value="'+esc(financePeriod.from)+'"></label><label>Au<input type="date" name="to" value="'+esc(financePeriod.to)+'"></label><button class="secondary">Appliquer</button><button type="button" id="allFinance" class="text-link">Tout l’historique</button></form><p class="finance-scope muted">Commandes créées sur la période sélectionnée, selon leur état actuel. Les paiements ne sont pas regroupés par date d’encaissement.</p>'+financeWorkspace(data,financeCurrency)+'<details class="cost-panel"><summary>Ajouter un frais général payé</summary><p class="muted">Exemples : emballage global, publicité, abonnement. Ne ressaisissez pas les achats ou transports déjà imputés aux commandes.</p><form id="expenseForm" class="settings-form"><div class="form-grid"><label>Date<input name="spent_on" type="date" required value="'+new Date().toISOString().slice(0,10)+'"></label><label>Devise<select name="currency"><option>EUR</option><option>XOF</option></select></label><label>Montant payé<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Catégorie<select name="category"><option>Publicité</option><option>Emballage</option><option>Abonnement</option><option>Autre frais général</option></select></label></div><label>Description<input name="description" maxlength="300" required></label><button class="primary">Enregistrer le frais</button><p class="inline-error" role="alert"></p></form></details><h2 class="finance-expenses-title">Frais généraux</h2><p class="muted">Dépenses datées dans la période, dans la devise sélectionnée.</p><div class="table-scroll"><table><thead><tr><th>Date</th><th>Libellé</th><th>Montant</th><th>État</th><th></th></tr></thead><tbody>'+data.expenses.filter(e=>e.currency===financeCurrency).map(e=>'<tr><td>'+esc(e.spent_on)+'</td><td>'+esc(e.category)+'<br>'+esc(e.description)+'</td><td>'+money(e.amount,e.currency)+'</td><td>'+(e.voided?'Annulé':'Enregistré')+'</td><td>'+(e.voided?'':'<button class="text-link" data-void-expense="'+esc(e.id)+'">Annuler cette saisie</button>')+'</td></tr>').join('')+'</tbody></table></div>'+(!data.expenses.some(e=>e.currency===financeCurrency)?'<p class="muted">Aucun frais général enregistré pour cette sélection.</p>':'')+'<p class="finance-footnote muted">Bilan de gestion, sans vérification bancaire. Devises séparées. Commandes de démonstration exclues des chiffres.</p></section>';
 $('#financePeriod').onsubmit=e=>{e.preventDefault();financePeriod=Object.fromEntries(new FormData(e.target));renderFinances(root)};
 $('#allFinance').onclick=()=>{financePeriod={from:'',to:''};renderFinances(root)};
 $$('[data-finance-currency]').forEach(b=>b.onclick=()=>{financeCurrency=b.dataset.financeCurrency;renderFinances(root)});
 $('#financeExport').onclick=()=>{activityFilters={...financePeriod,currency:financeCurrency,status:'',paid:'',search:''};section='report';renderAdmin()};
 const missing=$('#financeMissingCosts');if(missing)missing.onclick=async()=>{missing.disabled=true;const box=$('#financeMissingList');box.textContent='Chargement…';try{const result=await api('/api/admin/orders?'+new URLSearchParams({...financePeriod,currency:financeCurrency,status:'Livrée',realOnly:'1'}));if(request!==financeRequest)return;const orders=result.orders.filter(o=>!cancelledOrder(o)&&!refundedOrder(o)&&missingOrderCosts(o).length);box.innerHTML=orders.length?orders.map(o=>'<div class="finance-missing-row"><div><strong>'+esc(o.customer)+'</strong><small>'+esc(o.id.slice(0,11))+' · Manque : '+esc(missingOrderCosts(o).join(', '))+'</small></div><button class="secondary" data-complete-costs="'+esc(o.id)+'">Renseigner les montants</button></div>').join(''):'<p>Aucune commande avec des montants manquants dans cette sélection.</p>';$$('[data-complete-costs]').forEach(button=>button.onclick=()=>viewOrder(button.dataset.completeCosts,true))}catch(e){box.textContent=e.message}finally{missing.disabled=false}};
 const form=$('#expenseForm');let key=crypto.randomUUID();form.addEventListener('input',()=>key=crypto.randomUUID());
 form.elements.currency.onchange=()=>{const xof=form.elements.currency.value==='XOF';form.elements.amount.step=xof?'1':'0.01';form.elements.amount.min=xof?'1':'0.01'};
 form.elements.currency.value=financeCurrency;form.elements.currency.onchange();
 form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button');button.disabled=true;try{const b=Object.fromEntries(new FormData(form)),value=Number(b.amount);if(b.currency==='XOF'&&!Number.isInteger(value))throw new Error('Le montant XOF doit être entier.');await api('/api/admin/expense','POST',{...b,key,amount:Math.round(value*(b.currency==='EUR'?100:1))});renderFinances(root)}catch(err){form.querySelector('.inline-error').textContent=err.message;button.disabled=false}};
 $$('[data-void-expense]').forEach(button=>button.onclick=async()=>{if(!confirm('Annuler cette saisie ? Elle restera visible dans l’historique.'))return;button.disabled=true;try{await api('/api/admin/expense','PATCH',{id:button.dataset.voidExpense});renderFinances(root)}catch(err){toast(err.message);button.disabled=false}});
 }catch(e){if(section==='finances')root.innerHTML='<p class="form-error">'+esc(e.message)+'</p>'}
}

function addZoneRow(z={id:crypto.randomUUID(),country:'CI',name:'',fee:0,delay:'',enabled:false,confirmed:false,cod:false}){const box=document.createElement('fieldset');box.className='zone-row';box.dataset.id=z.id;box.innerHTML=`<legend>Zone de livraison · ${z.enabled&&z.confirmed?'Prête':'Brouillon'}</legend><div class="form-grid"><label>Pays<select name="country">${Object.entries(COUNTRIES).map(([code,name])=>`<option value="${code}" ${code===z.country?'selected':''}>${name}</option>`).join('')}</select></label><label>Nom de la zone<input name="name" value="${esc(z.name)}" required placeholder="Ex. Abidjan — Cocody"></label><label>Frais <span class="zone-currency">${z.country==='FR'?'EUR':'XOF'}</span><input name="fee" type="number" step="${z.country==='FR'?'0.01':'1'}" min="0" required value="${z.country==='FR'?z.fee/100:z.fee}"></label><label>Délai indicatif<input name="delay" value="${esc(z.delay)}" placeholder="Ex. 2 à 4 jours"></label></div><label class="check-label"><input name="coversNeighborhood" type="checkbox" ${z.coversNeighborhood?'checked':''}> Cette zone correspond déjà à un quartier</label><label class="check-label"><input name="cod" type="checkbox" ${z.cod?'checked':''}> Autoriser le paiement à la livraison</label><label class="check-label"><input name="confirmed" type="checkbox" ${z.confirmed?'checked':''}> Tarif et délai vérifiés par le gérant</label><label class="check-label"><input name="enabled" type="checkbox" ${z.enabled?'checked':''}> Ouvrir cette zone aux clientes</label><p class="muted">Une zone reste invisible tant que les conditions ne sont pas vérifiées et activées.</p><button class="text-link" type="button">Retirer cette zone du formulaire</button>`;$('#zones').append(box);box.querySelector('button').onclick=()=>box.remove();box.querySelector('select').onchange=e=>{box.querySelector('.zone-currency').textContent=e.target.value==='FR'?'EUR':'XOF';const fee=box.querySelector('[name=fee]');fee.step=e.target.value==='FR'?'0.01':'1';fee.value='';}}
async function saveZones(e){e.preventDefault();const button=e.target.querySelector('button.primary');button.disabled=true;try{const zones=$$('.zone-row').map(row=>{const f=name=>row.querySelector(`[name=${name}]`);const country=f('country').value;return {id:row.dataset.id,country,name:f('name').value,delay:f('delay').value,fee:country==='FR'?Math.round(Number(f('fee').value)*100):Number(f('fee').value),enabled:f('enabled').checked,confirmed:f('confirmed').checked,coversNeighborhood:f('coversNeighborhood').checked,cod:f('cod').checked}});await api('/api/admin/settings','PUT',{...management.settings,zones});await refreshAdmin();await load();toast('Zones et tarifs enregistrés.')}catch(err){e.target.querySelector('.inline-error').textContent=err.message;button.disabled=false}}
function mountVariantEditor(p,editing){
 const palette=paletteFor(management.settings.colors,p.variants),allSizes=[...STANDARD_SIZES,'Unique',...new Set(p.variants.map(v=>v.size).filter(s=>!STANDARD_SIZES.includes(s)&&s!=='Unique'))];
 const draft=stockDraft(p.variants),selectedSizes=new Set(p.variants.map(v=>v.size)),selectedColors=new Set(p.variants.map(v=>v.color));
 const originalSizes=new Set(selectedSizes),originalColors=new Set(selectedColors);
 const root=$('#variantEditor');
 root.innerHTML='<fieldset class="choice-field"><legend>Tailles proposées</legend><label class="check-label all-sizes"><input id="allSizes" type="checkbox"> Toutes les tailles · XS à XXL</label><div class="choice-list">'+allSizes.map((s,i)=>'<label class="choice"><input type="checkbox" data-size="'+i+'" '+(selectedSizes.has(s)?'checked':'')+'><span>'+esc(s==='Unique'?'Taille unique':s)+'</span></label>').join('')+'</div></fieldset>'+
 '<fieldset class="choice-field"><legend>Couleurs proposées</legend><div class="choice-list">'+palette.map((c,i)=>'<label class="choice"><input type="checkbox" data-color="'+i+'" '+(selectedColors.has(c.name)?'checked':'')+'>'+swatch(c.name,palette)+'<span>'+esc(c.name)+'</span></label>').join('')+'</div><p class="muted">La palette se règle dans Gestion → Couleurs du catalogue. Les couleurs de ce produit sont conservées.</p></fieldset>'+
 '<h3>Stock par taille et couleur</h3><p class="muted">Cochez les combinaisons proposées et renseignez leur quantité. Une quantité de 0 reste indisponible à l’achat. Une combinaison décochée sera retirée de la vente à l’enregistrement.</p><div id="stockMatrix"></div><p id="matrixSummary" class="muted" aria-live="polite"></p>';
 const sizeList=()=>allSizes.filter(s=>selectedSizes.has(s)),colorList=()=>palette.filter(c=>selectedColors.has(c.name)).map(c=>c.name);
 function summary(){const rows=selectedVariants(sizeList(),colorList(),draft);$('#matrixSummary').textContent=rows.length+' combinaison(s) proposée(s) · '+rows.reduce((sum,r)=>sum+(Number.isFinite(r.stock)?r.stock:0),0)+' pièce(s) en stock';}
 function render(){
  $$('[data-size]').forEach(input=>input.checked=selectedSizes.has(allSizes[+input.dataset.size]));
  $('#allSizes').checked=STANDARD_SIZES.every(s=>selectedSizes.has(s));$('#allSizes').indeterminate=!$('#allSizes').checked&&STANDARD_SIZES.some(s=>selectedSizes.has(s));
  const sizes=sizeList(),colors=colorList();if(!sizes.length||!colors.length){$('#stockMatrix').innerHTML='<p class="notice">Choisissez au moins une taille et une couleur pour renseigner les stocks.</p>';summary();return}
  const cells=[];for(const size of sizes)for(const color of colors){const key=variantKey(size,color);if(!draft.has(key))draft.set(key,{stock:0,enabled:!editing||!originalSizes.has(size)||!originalColors.has(color)});cells.push({size,color,key})}
  $('#stockMatrix').innerHTML='<div class="stock-table-scroll"><table class="stock-table"><thead><tr><th scope="col">Taille</th>'+colors.map(c=>'<th scope="col">'+swatch(c,palette)+esc(c)+'</th>').join('')+'</tr></thead><tbody>'+sizes.map(size=>'<tr><th scope="row">'+esc(size)+'</th>'+colors.map(color=>{const index=cells.findIndex(c=>c.size===size&&c.color===color),entry=draft.get(variantKey(size,color));return '<td><div class="stock-cell"><label class="check-label"><input type="checkbox" data-combination="'+index+'" '+(entry.enabled?'checked':'')+'><span class="sr-only">Proposer '+esc(size+' / '+color)+'</span></label><input type="number" min="0" max="100000" step="1" required aria-label="Stock '+esc(size+' / '+color)+'" data-stock="'+index+'" value="'+entry.stock+'" '+(entry.enabled?'':'disabled')+'></div></td>'}).join('')+'</tr>').join('')+'</tbody></table></div>';
  $$('[data-combination]').forEach(input=>input.onchange=()=>{const i=+input.dataset.combination;draft.get(cells[i].key).enabled=input.checked;$('#stockMatrix').querySelector('[data-stock="'+i+'"]').disabled=!input.checked;summary()});
  $$('[data-stock]').forEach(input=>input.oninput=()=>{draft.get(cells[+input.dataset.stock].key).stock=input.value===''?NaN:Number(input.value);summary()});summary();
 }
 $('#allSizes').onchange=e=>{if(e.target.checked){selectedSizes.delete('Unique');STANDARD_SIZES.forEach(s=>selectedSizes.add(s))}else STANDARD_SIZES.forEach(s=>selectedSizes.delete(s));render()};
 $$('[data-size]').forEach(input=>input.onchange=()=>{const s=allSizes[+input.dataset.size];if(input.checked){if(s==='Unique')selectedSizes.clear();else selectedSizes.delete('Unique');selectedSizes.add(s)}else selectedSizes.delete(s);render()});
 $$('[data-color]').forEach(input=>input.onchange=()=>{const c=palette[+input.dataset.color].name;if(input.checked)selectedColors.add(c);else selectedColors.delete(c);render()});render();
 return ()=>{const rows=selectedVariants(sizeList(),colorList(),draft);if(!rows.length)throw new Error('Choisissez au moins une combinaison taille/couleur.');if(rows.length>100)throw new Error('Limitez le produit à 100 combinaisons.');if(rows.some(v=>!Number.isSafeInteger(v.stock)||v.stock<0||v.stock>100000))throw new Error('Les stocks doivent être des nombres entiers positifs ou nuls.');return rows};
}
