 root.innerHTML='<p class="muted">Cette palette est proposée lors de la création des produits. Les couleurs des produits existants ne sont pas renommées.</p><form id="colorSettings"><div id="paletteRows" class="palette-grid"></div><button type="button" id="newColor" class="secondary">＋ Ajouter une couleur</button> <button class="primary">Enregistrer la palette</button><p class="inline-error" role="alert"></p></form>';
